namespace NotificationApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _allNotifications;

    public NotificationService()
    {
        _allNotifications = new List<NotificationItem>
        {
            new() { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new() { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new() { Id = _nextId++, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) },
        };
    }

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        return Task.FromResult(_allNotifications.OrderByDescending(n => n.Timestamp).ToList());
    }

    /// <summary>
    /// Returns notifications added after the given timestamp.
    /// Randomly generates a new notification ~30% of the time to simulate activity.
    /// </summary>
    public Task<List<NotificationItem>> GetNewNotificationsSinceAsync(DateTime since)
    {
        if (Random.Shared.NextDouble() < 0.3)
        {
            _allNotifications.Add(new NotificationItem
            {
                Id = _nextId++,
                Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                Timestamp = DateTime.UtcNow,
            });
        }

        var newer = _allNotifications
            .Where(n => n.Timestamp > since)
            .OrderByDescending(n => n.Timestamp)
            .ToList();

        return Task.FromResult(newer);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Items is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@Items.Count</span>
    }
</h1>

@if (IsPolling)
{
    <p class="text-muted"><em>Live — polling every 5 seconds</em></p>
}

@if (Items is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (Items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var item in Items)
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @item.Message
                <small class="text-muted">@item.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem>? Items { get; set; }

    private bool IsPolling;
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if state was NOT restored from prerender
        Items ??= await NotificationSvc.GetNotificationsAsync();
        _lastCheck = Items.Count > 0
            ? Items.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender never fires during prerender, so this
            // only starts once the page is fully interactive.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        IsPolling = true;
        await InvokeAsync(StateHasChanged);

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var newer = await NotificationSvc.GetNewNotificationsSinceAsync(_lastCheck);
                if (newer.Count > 0)
                {
                    Items = newer.Concat(Items!).ToList();
                    _lastCheck = Items.Max(n => n.Timestamp);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }

        IsPolling = false;
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

